# Kaggle kernel bootstrap for ATML PA4. Generated by scripts/kaggle_run.py -- do not edit the generated copy.
# CONFIG is substituted by the runner.
import json
import os
import shutil
import subprocess
import sys
import time
from datetime import datetime, timezone
from pathlib import Path

CONFIG = json.loads(r'''__CONFIG__''')

T0 = time.time()
WORK = Path("/kaggle/working")
REPO = Path("/tmp/atml4_repo")
LOGS = WORK / "logs"
LOGS.mkdir(parents=True, exist_ok=True)
STEPS = []


def sh(cmd, log_name, cwd=None, env=None, check=True):
    t = time.time()
    print(f"\n=== [{log_name}] $ {cmd}", flush=True)
    with open(LOGS / f"{log_name}.log", "w") as lf:
        p = subprocess.Popen(cmd, shell=True, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                             text=True, bufsize=1)
        for line in p.stdout:
            sys.stdout.write(line)
            lf.write(line)
        rc = p.wait()
    STEPS.append({"step": log_name, "cmd": cmd, "rc": rc, "seconds": round(time.time() - t, 2)})
    if check and rc != 0:
        raise RuntimeError(f"step {log_name} failed rc={rc}")
    return rc


def capture(cmd):
    try:
        return subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=60).stdout
    except Exception as e:
        return f"error: {e}"


def find_prepared_data():
    """Locate prepared-data directories from kernel_sources (any dir containing local_source_revisions.json)."""
    hits = []
    root = Path("/kaggle/input")
    if root.exists():
        for p in root.rglob("local_source_revisions.json"):
            hits.append(p.parent)
    return hits


def find_prefix_banks():
    """Locate prefix-bank output dirs from kernel_sources (dirs containing prefix_banks_locked.jsonl.gz)."""
    root = Path("/kaggle/input")
    return sorted({p.parent for p in root.rglob("prefix_banks_locked.jsonl.gz")}) if root.exists() else []


run_meta = {"config": CONFIG, "start_utc": datetime.now(timezone.utc).isoformat(timespec="seconds"),
            "nvidia_smi": capture("nvidia-smi"),
            "nvidia_smi_query": capture("nvidia-smi --query-gpu=index,name,memory.total,driver_version,"
                                        "compute_cap --format=csv"),
            "kaggle_env": {k: v for k, v in os.environ.items() if k.startswith("KAGGLE_")}}
print(run_meta["nvidia_smi"] or "nvidia-smi: not available (CPU kernel)", flush=True)
rc_main = None
error = None
try:
    REPO.parent.mkdir(parents=True, exist_ok=True)
    sh(f"git clone --quiet {CONFIG['repo_url']} {REPO}", "git_clone")
    sh(f"git checkout --quiet {CONFIG['commit']}", "git_checkout", cwd=REPO)
    sh("git submodule update --init --recursive", "git_submodule", cwd=REPO)
    sh(f"{sys.executable} -m pip install -q -r env/requirements.txt", "pip_install", cwd=REPO)
    data_dst = REPO / "external/atml-pa4-datasets/data"
    mounted = find_prepared_data()
    run_meta["mounted_data_dirs"] = [str(p) for p in mounted]
    for src in mounted:
        print(f"Merging prepared data from {src} into {data_dst}", flush=True)
        shutil.copytree(src, data_dst, dirs_exist_ok=True)
    banks = find_prefix_banks()
    run_meta["mounted_prefix_bank_dirs"] = [str(p) for p in banks]
    for src in banks:
        print(f"Merging prefix banks from {src} into {data_dst / 'prefix_banks'}", flush=True)
        shutil.copytree(src, data_dst / "prefix_banks", dirs_exist_ok=True)
    env = dict(os.environ)
    env["PYTHONPATH"] = str(REPO / "src") + os.pathsep + env.get("PYTHONPATH", "")
    env["ATML4_KERNEL_SLUG"] = CONFIG["kernel_slug"]
    env["ATML4_ROOT"] = str(REPO)
    env["ATML4_GIT_COMMIT"] = CONFIG["commit"]
    env["PYTHONUNBUFFERED"] = "1"
    t_cmd = time.time()
    rc_main = sh(CONFIG["command"], "main", cwd=REPO, env=env, check=False)
    run_meta["command_seconds"] = round(time.time() - t_cmd, 2)
except Exception as e:  # recorded, outputs still copied
    error = repr(e)
    print("BOOTSTRAP ERROR:", error, flush=True)
finally:
    if REPO.exists():
        for rel in ["results", *CONFIG.get("outputs", [])]:
            src = REPO / rel
            if src.exists():
                dst = WORK / Path(rel).name if rel != "results" else WORK / "results"
                if src.is_dir():
                    shutil.copytree(src, dst, dirs_exist_ok=True)
                else:
                    shutil.copy2(src, dst)
    run_meta.update({"end_utc": datetime.now(timezone.utc).isoformat(timespec="seconds"),
                     "wall_seconds": round(time.time() - T0, 2), "exit_code": rc_main, "error": error,
                     "steps": STEPS, "accelerator_requested": CONFIG.get("accelerator"),
                     "gpu_names": [l.split(",")[1].strip() for l in run_meta["nvidia_smi_query"].splitlines()[1:]
                                   if l.count(",") >= 4]})
    (WORK / "run_meta.json").write_text(json.dumps(run_meta, indent=1))
    print("run_meta:", json.dumps({k: run_meta[k] for k in ("wall_seconds", "exit_code", "error", "gpu_names")}),
          flush=True)
